/// <summary>
/// Coc for allowedStatuses
/// </summary>
/// <returns>Container</returns>
public static container allowedStatuses()
{
    next allowedStatuses();

    return [
         CredManDocumentStatusCheck::METCreditCheck,
            CredManDocumentStatusCheck::Confirmation,
            CredManDocumentStatusCheck::PickingList,
            CredManDocumentStatusCheck::WHSShipment,
            CredManDocumentStatusCheck::PackingSlip,
            CredManDocumentStatusCheck::Invoice
           ];
}

/// <summary>
/// Coc for checkDocumentStatus
/// </summary>
/// <param name = "_documentStatus">DocumentStatus</param>
/// <returns>Boolean</returns>
protected static boolean checkDocumentStatus(CredManDocumentStatusCheck _documentStatus)
{
    boolean isDocumentStatus = next checkDocumentStatus(_documentStatus);
    if (!isDocumentStatus)
    {
        switch (_documentStatus)
        {
            case CredManDocumentStatusCheck::METCreditCheck :
                isDocumentStatus = true;
                break;
        }
    }
    return isDocumentStatus;

}

/// <summary>
/// Coc for documentStatus2DocumentStatusCheck
/// </summary>
/// <param name = "_documentStatus">Document status</param>
/// <returns>CredManDocumentStatusCheck</returns>
protected internal static CredManDocumentStatusCheck documentStatus2DocumentStatusCheck(DocumentStatus _documentStatus)
{
    CredManDocumentStatusCheck credManDocumentStatusCheck ;
    credManDocumentStatusCheck =  next documentStatus2DocumentStatusCheck(_documentStatus);

    if (_documentStatus == DocumentStatus::METCreditCheck)
    {
        credManDocumentStatusCheck = CredManDocumentStatusCheck::METCreditCheck;
    }
    return credManDocumentStatusCheck;
}
